with parsed as (select id, customer_id, items, ship_to, attributes, array_contains(map_keys(attributes), 'weight_kg') as has_weight_kg, aggregate(items, 0.0D, (acc, item) -> acc + item.qty * item.price, acc -> round(acc, 2)) as cart_value, array_join(array_sort(coupon_codes), ',') as coupons_text, coalesce(attributes['gift'], 'direct') as gift_or_default from carts where customer_id in (16, 18, 19)) select customer_id, count(*) as event_count, avg(cart_value) as avg_cart_value, percentile_approx(cart_value, 0.95) as cart_value_p95, count(distinct id) as distinct_ids, max(cart_value) as max_cart_value, grouping_id() as gid from parsed group by rollup (customer_id) order by max_cart_value desc;
